/// Registry entry for `hydraulics.packing_sizing`.
static PACKING_SIZING_CHECKS: &[SpecCheck] = &[
    SpecCheck {
        on_input: true,
        check: RangeCheck {
            quantity: "design_flood_fraction",
            min: Some(0.0),
            min_inclusive: false,
            max: None,
            max_inclusive: true,
            equals: None,
            band: Band::Outside,
            severity: Severity::Error,
            code: WarningCode::OutOfValidRange,
            rationale: "a design fraction of zero sizes the column for a velocity of zero, which is an infinite area. The class answers that state with its `1.0` m trial rather than an error, and a caller asking for an unphysical column should be told rather than handed the trial.",
        },
    },
    SpecCheck {
        on_input: true,
        check: RangeCheck {
            quantity: "vapor_density",
            min: Some(0.0),
            min_inclusive: false,
            max: None,
            max_inclusive: true,
            equals: None,
            band: Band::Outside,
            severity: Severity::Error,
            code: WarningCode::OutOfValidRange,
            rationale: "the volumetric flow divides by the vapour density. The class floors it at `0.01` kg/m**3 so the division is defined, which is a guard rather than a physical range; a non-positive density is a state no gas is in.",
        },
    },
    SpecCheck {
        on_input: true,
        check: RangeCheck {
            quantity: "liquid_density",
            min: Some(0.0),
            min_inclusive: false,
            max: None,
            max_inclusive: true,
            equals: None,
            band: Band::Outside,
            severity: Severity::Error,
            code: WarningCode::OutOfValidRange,
            rationale: "the density factor is `rho_v / (g (rho_l - rho_v))`, so a liquid no denser than the vapour makes it singular or negative - physically not a two-phase contactor.",
        },
    },
    SpecCheck {
        on_input: true,
        check: RangeCheck {
            quantity: "liquid_viscosity",
            min: Some(0.0),
            min_inclusive: false,
            max: None,
            max_inclusive: true,
            equals: None,
            band: Band::Outside,
            severity: Severity::Error,
            code: WarningCode::OutOfValidRange,
            rationale: "a dynamic viscosity is a positive quantity; it is used as a ratio to water raised to a fractional power.",
        },
    },
    SpecCheck {
        on_input: true,
        check: RangeCheck {
            quantity: "vapor_mass_flow",
            min: Some(0.0),
            min_inclusive: true,
            max: None,
            max_inclusive: true,
            equals: None,
            band: Band::Outside,
            severity: Severity::Warning,
            code: WarningCode::OutOfValidRange,
            rationale: "no vapour flow gives an area of zero and therefore the table's `0.3` m floor: a real answer to a degenerate question, so this is a warning rather than an error.",
        },
    },
];

